function vReady(){var b=0;try{for(var i=0;i<v.buffered.length;i++){if(v.currentTime>=v.buffered.start(i)-0.3&&v.currentTime<=v.buffered.end(i)){b=v.buffered.end(i)-v.currentTime}}}catch(e){}return v.readyState>=3&&(b>=6||(v.duration&&b>=v.duration-v.currentTime-0.5))}
