PG.cpr=function(){return polHd('© '+T('سياسة حقوق الملكية','Copyright policy'))+'<div class="note">'+T('شوف كرتون لا يستضيف أي ملف فيديو. جميع الأعمال تُبثّ من أرشيف الإنترنت (Internet Archive) أو مصادر مفتوحة، وحقوق كل عمل محفوظة لأصحابه ولشركات إنتاجه.','Shoof Cartoon hosts no video files. All works stream from the Internet Archive or open sources, and the rights to each work belong to their owners and producers.')+'</div><h3 class="h3">\uD83D\uDCE9 '+T('هل أنت صاحب حق؟','Are you a rights holder?')+'</h3><div class="note">'+T('إذا كنت مالك عمل أو ممثله وتريد إزالة عمل من الموقع، افتح صفحة \uD83D\uDEA9 البلاغ واكتب اسم العمل ورابطه وما يثبت ملكيتك، وسننظر في الطلب بأسرع وقت ونحجب العمل من الموقع عند التأكد. ولإزالته نهائيًا من مصدره راجع أرشيف الإنترنت مباشرة.','If you own a work or represent its owner and want it removed, open the \uD83D\uDEA9 Report page and send the work name, its link and proof of ownership. We will review it as soon as possible and hide the work from the site once verified. To remove it permanently from its source, contact the Internet Archive directly.')+'</div><div class="note">'+T('العلامات التجارية وأسماء الشخصيات والشعارات الظاهرة هي ملك لأصحابها، وذكرها هنا للتعريف فقط ولا يعني أي ارتباط أو رعاية.','Trademarks, character names and logos shown belong to their owners and are mentioned for identification only, with no affiliation or endorsement implied.')+'</div><div class="more"><button class="btn" id="cprr" type="button">\uD83D\uDEA9 '+T('تقديم طلب إزالة','Submit a removal request')+'</button></div>'+'<div class="more"><a class="btn g" href="#p=use">\uD83D\uDCDC '+T('سياسة الاستخدام','Terms of use')+'</a> <a class="btn g" href="#p=cpr">© '+T('حقوق الملكية','Copyright')+'</a> <a class="btn g" href="#p=prv">\uD83D\uDD10 '+T('الخصوصية','Privacy')+'</a> <a class="btn g" href="#p=flt">\uD83D\uDEE1 '+T('فلتر الأمان v10','Safety filter v10')+'</a></div>'}
PG.prv=function(){return polHd('\uD83D\uDD10 '+T('سياسة الخصوصية','Privacy policy'))+'<div class="note">'+T('نحترم خصوصيتك، وهذا ما نجمعه وما نفعله به:','We respect your privacy. Here is what we collect and what we do with it:')+'</div><div class="note">'+T('• بيانات على جهازك فقط: المفضلة والنقاط والإعدادات وحد المشاهدة وحسابك المحلي، وتُحفظ في متصفحك ويمكنك مسحها في أي وقت.<br>• عند إنشاء حساب يصلنا الاسم والمعرّف والعمر والبلد والبريد (اختياري) ووقت التسجيل ومعلومات بسيطة عن الجهاز لتحسين الموقع.<br>• الإعلانات: قد يعرض الموقع إعلانات Google AdSense، وقد تستخدم Google ملفات الارتباط لعرض إعلانات مناسبة، ويمكنك إدارتها من إعدادات إعلانات Google.<br>• لا نبيع بياناتك. ولا نطلب كلمة مرور أو بيانات دفع.<br>• للأطفال: لا نجمع بيانات حساسة، ونوصي بالتسجيل بإشراف الأهل. ويمكنكم طلب حذف بيانات طفلكم من صفحة البلاغ.','• Data on your device only: favorites, points, settings, watch limit and your local account, stored in your browser and removable any time.<br>• When you create an account we receive the name, ID, age, country, optional email, sign-up time and basic device info to improve the site.<br>• Ads: the site may show Google AdSense ads, and Google may use cookies to show relevant ads; you can manage this in Google ad settings.<br>• We do not sell your data and never ask for passwords or payment details.<br>• Children: we collect no sensitive data and recommend signing up with a parent. Parents can request deletion of a child’s data from the Report page.')+'</div>'+'<div class="more"><a class="btn g" href="#p=use">\uD83D\uDCDC '+T('سياسة الاستخدام','Terms of use')+'</a> <a class="btn g" href="#p=cpr">© '+T('حقوق الملكية','Copyright')+'</a> <a class="btn g" href="#p=prv">\uD83D\uDD10 '+T('الخصوصية','Privacy')+'</a> <a class="btn g" href="#p=flt">\uD83D\uDEE1 '+T('فلتر الأمان v10','Safety filter v10')+'</a></div>'}
PG.flt=function(){return polHd('\uD83D\uDEE1 '+T('فلتر الأمان v10','Safety filter v10'))+'<div class="note">'+T('فلتر الأمان v10 هو نظام حماية تلقائي من عدة طبقات يعمل في كل بحث وكل بطاقة وكل فيديو، ليبقى الموقع مناسبًا للعائلة.','Safety filter v10 is an automatic multi-layer protection system that runs on every search, every card and every video to keep the site family-friendly.')+'</div><h3 class="h3">\uD83E\uDDF1 '+T('طبقاته','Its layers')+'</h3><div class="note">'+T('1) فحص عنوان العمل وموضوعاته وصانعه ومعرّفه بقائمة كلمات محظورة بالإنجليزية والعربية، مع كشف التحايل بالأرقام والرموز مثل p0rn.<br>2) فحص الوصف وتصنيف المجموعة وحجب أقسام البالغين بالكامل.<br>3) استبعاد المواضيع غير اللائقة من البحث نفسه قبل ظهور النتائج.<br>4) رفض كلمات البحث المحظورة قبل إرسالها.<br>5) إعادة الفحص عند فتح الفيديو، فإن لم يمر لا يُعرض.<br>6) فلتر أعمال "ليست كرتون": يخفي مقاطع الأخبار والسياسة واليوتيوب والأسماء المشفّرة، ويُظهر فقط ما له دليل أنه كرتون ولديه ملف فيديو قابل للتشغيل.<br>7) زر \uD83D\uDEA9 للإبلاغ، وركن الأهل بحد المشاهدة ورمز PIN.','1) Checks a work’s title, subjects, creator and ID against banned-word lists in English and Arabic, and catches tricks such as p0rn.<br>2) Checks the description and collection, and blocks adult collections entirely.<br>3) Excludes inappropriate topics from the search itself before results appear.<br>4) Rejects banned search words before they are sent.<br>5) Re-checks when a video opens; if it fails, it is not shown.<br>6) A “not a cartoon” filter hides news, politics, YouTube clips and coded names, and shows only works with evidence of being a cartoon and a playable video file.<br>7) A \uD83D\uDEA9 report button, and a parents corner with watch limit and PIN.')+'</div><h3 class="h3">\uD83E\uDDEA '+T('الاختبار','Testing')+'</h3><div class="note">'+T('اختُبر الفلتر على عناوين حلقات حقيقية وكلمات محظورة بالإنجليزية والعربية: حجب الكلمات الصريحة وصيغ التحايل، ومرّرت العناوين العادية مثل Tom and Jerry وEssex وCassandra. وهو متحفّظ عمدًا، فقد يحجب أحيانًا عنوانًا بريئًا يحوي كلمة حساسة.','The filter was tested on real episode titles and banned words in English and Arabic: explicit words and tricks are blocked, and normal titles such as Tom and Jerry, Essex and Cassandra pass. It is deliberately cautious, so it may occasionally block an innocent title containing a sensitive word.')+'</div><div class="note">⚠ '+T('لا يوجد فلتر آلي مضمون 100%. إن رأيت ما لا يناسب فاضغط \uD83D\uDEA9 وسنحجبه.','No automatic filter is 100% guaranteed. If you see something unsuitable, tap \uD83D\uDEA9 and we will block it.')+'</div>'+'<div class="more"><a class="btn g" href="#p=use">\uD83D\uDCDC '+T('سياسة الاستخدام','Terms of use')+'</a> <a class="btn g" href="#p=cpr">© '+T('حقوق الملكية','Copyright')+'</a> <a class="btn g" href="#p=prv">\uD83D\uDD10 '+T('الخصوصية','Privacy')+'</a> <a class="btn g" href="#p=flt">\uD83D\uDEE1 '+T('فلتر الأمان v10','Safety filter v10')+'</a></div>'}
