PB.cpr=function(){var b=$('cprr');if(b)b.onclick=function(){go('rep')}};
PB.acc=function(){var g=function(i,f){var e=$(i);if(e)e.onclick=f};var cp=$('acap');if(cp)cp.onchange=function(){$('acw').style.display=cp.checked?'block':'none'};
g('areg',function(){if(!$('acap')||!$('acap').checked){toast(T('أكّد أنك لستَ روبوتًا','Please confirm you are not a robot'));return}if(+($('acv').value||0)!==capA+capB){toast(T('إجابة التحقق غير صحيحة','Wrong verification answer'));return}if($('ahp').value||Date.now()-capT<2500){toast(T('انتظر ثانية ثم أعد المحاولة','Wait a second and retry'));return}var n=$('an').value.replace(/\s+/g,' ').trim().slice(0,20);if(!n){toast(T('اكتب اسمك','Enter your name'));return}var ag=parseInt(($('aa')?$('aa').value:'').trim(),10);if(!(ag>=3&&ag<=99)){toast(T('اكتب عمرك (إجباري) من 3 إلى 99','Enter your age (required), 3 to 99'));return}var ck=($('ac')?$('ac').value:'').replace(/\s+/g,' ').trim().slice(0,30);if(ck.length<2){toast(T('اكتب بلدك (إجباري)','Enter your country (required)'));return}var em=($('ae')?$('ae').value:'').trim();if(em&&!/^\S+@\S+\.\S+$/.test(em)){toast(T('البريد غير صحيح','Invalid email'));return}var l=accs(),id=newId();var ts=nowStr();l.push({id:id,n:n,a:ag,k:ck,c:today(),tm:ts,f:0});ss('accs',l);ss('me',id);sendRep('تسجيل عضو جديد','member','',regInfo(n,ag,id,ts,ck),em,id);folUi();renderPage('acc');toast('\uD83C\uDD94 '+id)});
g('aage',function(){var m=me(),a=parseInt(($('aa2')?$('aa2').value:'').trim(),10);if(!m)return;if(!(a>=3&&a<=99)){toast(T('اكتب عمرك (إجباري) من 3 إلى 99','Enter your age (required), 3 to 99'));return}var l=accs();l.forEach(function(x){if(x.id===m.id)x.a=a});ss('accs',l);sendRep('تحديث عمر عضو','member','','الاسم: '+m.n+' | ID: '+m.id+' | العمر: '+a+' | وقت التحديث: '+nowStr(),'',m.id);renderPage('acc')});
g('ackb',function(){var m=me(),k=($('ac2')?$('ac2').value:'').replace(/\s+/g,' ').trim().slice(0,30);if(!m)return;if(k.length<2){toast(T('اكتب بلدك (إجباري)','Enter your country (required)'));return}var l=accs();l.forEach(function(x){if(x.id===m.id)x.k=k});ss('accs',l);sendRep('تحديث بلد عضو','member','','الاسم: '+m.n+' | ID: '+m.id+' | البلد: '+k+' | وقت التحديث: '+nowStr(),'',m.id);renderPage('acc')});
g('alog',function(){var id=$('ai').value.trim().toUpperCase(),ok=accs().some(function(a){return a.id===id});if(!ok){toast(T('المعرّف غير موجود على هذا الجهاز','ID not found on this device'));return}ss('me',id);folUi();renderPage('acc')});
g('afol',toggleFol);
g('acp',function(){var m=me();if(m&&navigator.clipboard)navigator.clipboard.writeText(m.id).then(function(){toast(T('تم نسخ المعرّف ✔','ID copied ✔'))})});
g('aout',function(){ss('me','');folUi();renderPage('acc')});
g('adel',function(){var m=me();if(m&&confirm(T('حذف الحساب من هذا الجهاز؟','Delete this account from this device?'))){ss('accs',accs().filter(function(a){return a.id!==m.id}));ss('me','');folUi();renderPage('acc')}})};
